const int trigPin = 9;   // Trig датчика HC-SR04
const int echoPin = 10;  // Echo датчика HC-SR04
const int ledPin = 3;   // Светодиод (можно поменять на любой другой цифровой пин)

void setup() {
  Serial.begin(9600);    // Для отладки: смотрим расстояние в мониторе порта

  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  pinMode(ledPin, OUTPUT);
}

void loop() {
  // Инициализация замера расстояния
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Чтение времени импульса
  long duration = pulseIn(echoPin, HIGH);

  // Перевод времени в расстояние (в см)
  int distance = duration / 58.2;

  // Вывод расстояния в монитор порта (для проверки)
  Serial.print("Расстояние: ");
  Serial.print(distance);
  Serial.println(" см");

  // Логика управления светодиодом
  if (distance < 20 && distance > 0) {  // Объект близко (и расстояние реально)
    digitalWrite(ledPin, HIGH);         // Включить светодиод
  } else {
    digitalWrite(ledPin, LOW);          // Выключить светодиод
  }

  delay(100); // Небольшая задержка для стабильности
}
